MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(:Category {name: 'Bikes'})
WHERE EXISTS {
  MATCH (o:SalesOrder)-[:HAS_LINE]->(p), (o)-[:IN_TERRITORY]->(:Territory {name: 'Southwest'})
  WHERE date_part('year', o.order_date) = 2025
}
AND NOT EXISTS {
  MATCH (o:SalesOrder)-[:HAS_LINE]->(p), (o)-[:IN_TERRITORY]->(:Territory {name: 'Central'})
  WHERE date_part('year', o.order_date) = 2025
}
RETURN DISTINCT p.product_number AS product_number
ORDER BY product_number;
